    @EventHandler( payloadType=CreateLoanEvent.class )
    public void handle( CreateLoanEvent event) {
	    LOGGER.info("handling CreateLoanEvent - " + event );
	    Loan entity = new Loan();
            entity.setLoanId( event.getLoanId() );
            entity.setLoanNumber( event.getLoanNumber() );
            entity.setPrincipal( event.getPrincipal() );
            entity.setInterestRate( event.getInterestRate() );
            entity.setOriginationDate( event.getOriginationDate() );
            entity.setMaturityDate( event.getMaturityDate() );
            entity.setRateType( event.getRateType() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllLoan( entity );
    }

