            entity.setCustomer( event.getCustomer() );
            entity.setSchedule( event.getSchedule() );
            entity.setCollateral( event.getCollateral() );
            entity.setTransactions( event.getTransactions() );
            entity.setRateType( event.getRateType() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
