    /**
     * Method to retrieve the Loan via an LoanPrimaryKey.
     * @param 	id Long
     * @return 	Loan
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Loan handle( FindLoanQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getLoanId() );
    }
    
    /**
     * Method to retrieve a collection of all Loans
     *
     * @param	query	FindAllLoanQuery 
     * @return 	List<Loan> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Loan> handle( FindAllLoanQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindLoan,
 * but only if the id matches
 *
 * @param		entity	Loan
 */
	protected void emitFindLoan( Loan entity ) {
		LOGGER.info("handling emitFindLoan" );
		
	    queryUpdateEmitter.emit(FindLoanQuery.class,
	                            query -> query.getFilter().getLoanId().equals(entity.getLoanId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllLoan
	 * 
	 * @param		entity	Loan
	 */
	protected void emitFindAllLoan( Loan entity ) {
		LOGGER.info("handling emitFindAllLoan" );
		
	    queryUpdateEmitter.emit(FindAllLoanQuery.class,
	                            query -> true,
	                            entity);
	}

